def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = []
    op = []
    opp_d = 0
    for m, o in history:
        my.append(m)
        op.append(o)
        if o == 'D':
            opp_d += 1

    opp_c = n - opp_d
    my_last = my[-1]
    op_last = op[-1]

    opp_d5 = sum(1 for x in op[-5:] if x == 'D')
    opp_d10 = sum(1 for x in op[-10:] if x == 'D')

    s = 0
    for x in reversed(op):
        if x == 'D':
            s += 1
        else:
            break

    ms = 0
    for x in reversed(my):
        if x == 'D':
            ms += 1
        else:
            break

    tol = 0
    pun = 0
    unprov = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if op[i + 1] == 'C':
                tol += 1
            else:
                pun += 1
        if my[i] == 'C' and op[i + 1] == 'D':
            unprov += 1

    if n >= 3 and opp_d * 3 >= 2 * n and opp_d5 >= 2:
        return 'D'
    if opp_d * 3 >= 2 * n and s >= 2:
        return 'D'
    if opp_d5 >= 5 and opp_d * 2 >= n:
        return 'D'
    if opp_d10 >= 8 and opp_d * 2 >= n:
        return 'D'
    if opp_d * 2 >= n and (op_last == 'D' or opp_d5 >= 2):
        return 'D'

    very_coop = opp_c * 4 >= 3 * n
    high_coop = opp_c * 3 >= 2 * n
    low_recent = opp_d5 <= 1
    ok_recent = opp_d5 <= 2
    few_unprov = unprov <= max(1, n // 10)
    low_punish_rate = pun * 5 <= tol + 1

    if op_last == 'C':
        if my_last == 'D':
            if opp_d == 0:
                if tol == 0:
                    return 'C'
                return 'D'
            if ms <= 8:
                if pun == 0 and tol > 0 and very_coop and low_recent:
                    return 'D'
                if tol > pun and low_punish_rate and high_coop and ok_recent and few_unprov:
                    if rng.random() < 0.55:
                        return 'D'
                return 'C'
            return 'C'
        else:
            if opp_d == 0:
                return 'D'
            if pun == 0 and tol > 0 and very_coop and low_recent:
                return 'D'
            if tol > pun and low_punish_rate and high_coop and ok_recent and few_unprov:
                if rng.random() < 0.35:
                    return 'D'
            if n >= 98 and tol > 0:
                if pun == 0 and opp_c > opp_d and low_recent:
                    return 'D'
                if tol > pun and low_punish_rate and opp_c > opp_d and ok_recent:
                    return 'D'
            return 'C'

    if my_last == 'D':
        if opp_c * 3 >= 2 * n and s <= 2 and ok_recent:
            return 'C'
        if opp_c > opp_d and s <= 3 and opp_d5 <= 3 and few_unprov:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'

    provoked = False
    if n >= 2 and my[-2] == 'D':
        provoked = True
    if n >= 3 and my[-3] == 'D' and op[-2] == 'D':
        provoked = True

    if provoked and opp_c >= opp_d and s <= 2 and ok_recent:
        return 'C'
    if opp_c > opp_d and s == 1 and low_recent:
        return 'D'
    if s >= 2 or opp_d5 >= 3 or opp_c <= opp_d:
        return 'D'
    if opp_c * 3 >= 2 * n and s <= 1:
        return 'C'
    return 'D'
